<article class="article-page"><header class="article-hero"><div class="container container--md"><div class="breadcrumb"><a href="/articles"><?= e(t('nav.articles')) ?></a><span><?= icon('arrow-left') ?></span><span><?= e($article['type']) ?></span></div><span class="eyebrow">Mentoris Journal</span><h1><?= e($article['title']) ?></h1><p><?= e($article['excerpt']) ?></p><div class="article-meta"><span><?= icon('user') ?> <?= e($article['author']) ?></span><span><?= icon('clock') ?> <?= e($article['read']) ?></span><time class="ltr" datetime="<?= e(substr($article['published_at'], 0, 10)) ?>"><?= e(substr($article['published_at'], 0, 10)) ?></time></div></div></header>
<?php if (!empty($article['image'])): ?><div class="container container--md article-cover"><img src="<?= asset($article['image']) ?>" alt="<?= e($article['title']) ?>" width="1536" height="1024"></div><?php endif; ?>
<?php if (!empty($article['sections'])): ?><nav class="container container--sm article-toc" aria-label="فهرست این مقاله"><strong>در این یادداشت</strong><ol><?php foreach ($article['sections'] as $index=>$section): ?><li><a href="#section-<?= $index+1 ?>"><?= e($section['heading']) ?></a></li><?php endforeach; ?></ol></nav><?php endif; ?>
<div class="container container--sm article-body"><?php if (!empty($article['sections'])): ?><?php foreach ($article['sections'] as $index=>$section): ?><section id="section-<?= $index+1 ?>"><h2><?= e($section['heading']) ?></h2><p><?= nl2br(e($section['body'])) ?></p></section><?php endforeach; ?><?php else: ?><?php foreach (preg_split('/\n\s*\n/u',(string)$article['body']) ?: [] as $paragraph): if (trim($paragraph) === '') continue; ?><p><?= nl2br(e(trim($paragraph))) ?></p><?php endforeach; ?><?php endif; ?></div></article>
<?php if (!empty($article['references'])): ?><aside class="container container--sm article-sources"><h2>منابع برای مطالعه بیشتر</h2><ul><?php foreach ($article['references'] as [$label,$url]): ?><li><a href="<?= e($url) ?>" target="_blank" rel="noopener noreferrer"><?= e($label) ?></a></li><?php endforeach; ?></ul></aside><?php endif; ?>
<section class="container container--md article-bridge"><div><span class="eyebrow">از دانستن تا تمرین</span><h2>در اجرای این رویکرد با خستگی یا مقاومت مراجع روبه‌رو می‌شوید؟</h2><p>در حلقه درمانگران منتوریس، مهارت بالینی و تاب‌آوری حرفه‌ای را با گفت‌وگو و تمرین پی می‌گیریم.</p><a class="btn btn--primary" href="/events/therapists-circle-second">آشنایی با حلقه درمانگران</a></div></section>
<?php if (!empty($relatedArticles)): ?><section class="section article-related"><div class="container"><header class="section__head"><div><span class="eyebrow">مطالعه بعدی</span><h2>در همین مسیر بیشتر بخوانید</h2></div><a href="/articles" class="btn btn--secondary">همه مقاله‌ها</a></header><div class="grid grid--3 articles-grid"><?php foreach ($relatedArticles as $article): require view_path('components/cards/article-card.php'); endforeach; ?></div></div></section><?php endif; ?>
